## TASK 2: PopIn wrapper component
====================================================================

### File: Create `client/src/components/pop-in.tsx`

```tsx
// client/src/components/pop-in.tsx
import { motion } from "framer-motion";
import { CSSProperties, ReactNode } from "react";
import { OVERSHOOT, POP_DURATION, STAGGER_STEP, prefersReducedMotion } from "@/lib/motion";

/**
 * Wraps content in the signature bounce/pop-in entrance. Pass `index` to stagger
 * siblings. Honours prefers-reduced-motion with a plain fade (no transform).
 */
export function PopIn({
  children, index = 0, className, style,
}: { children: ReactNode; index?: number; className?: string; style?: CSSProperties }) {
  const reduced = prefersReducedMotion();
  return (
    <motion.div
      className={className}
      style={style}
      initial={reduced ? { opacity: 0 } : { opacity: 0, y: 12, scale: 0.97 }}
      animate={reduced ? { opacity: 1 } : { opacity: 1, y: 0, scale: 1 }}
      transition={reduced
        ? { duration: 0.2, ease: "easeOut", delay: index * 0.03 }
        : { duration: POP_DURATION, ease: OVERSHOOT, delay: index * STAGGER_STEP }}
    >
      {children}
    </motion.div>
  );
}
```

### Verify: `npx vite build` succeeds (no type/import errors from this file).

### Commit:
```bash
git add client/src/components/pop-in.tsx
git commit -m "feat(motion): PopIn wrapper with reduced-motion fallback"
```

